var instances_q7 = [].concat(
  // q7 :- q7_volume(_,_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q7', [], e1.v]];
    }, _.values(q7_volume)));
  })()
);
var q7 = relation({}, instances_q7);

// component 0 bool
var model = function() {
  return [holds(q7, [])()];
};
Infer({method: 'enumerate'}, model);

